/// <summary>
/// MPJ_5013_ExciseRegister
/// The <c>METExciseRegisterReceiptVarianceDP</c> class is the report data provider class for the Excise Register Underbond Receipt Variance Report
/// </summary>
[
    SRSReportParameterAttribute(classStr(METExciseRegisterReceiptVarianceContract))
]
class METExciseRegisterReceiptVarianceDP extends SrsReportDataProviderPreProcessTempDB
{
    METExciseRegisterReceiptVarianceTmp        varianceTmpTable;
    METExciseRegisterReceiptVarianceContract   contract;

}

Method.Source:
/// <summary>
/// Fetches data from the <c>METExciseRegisterReceiptVarianceTmp</c> temporary table.
/// </summary>
/// <returns>
/// The data from <c>METExciseRegisterReceiptVarianceTmp</c> table.
/// </returns>
[
    SRSReportDataSetAttribute(tableStr(METExciseRegisterReceiptVarianceTmp))
]
public METExciseRegisterReceiptVarianceTmp getinventOnhandTmp()
{
    select  varianceTmpTable;
    return  varianceTmpTable;
}

    /// <summary>
    /// Processes the report business logic.
    /// </summary>
    /// <remarks>
    /// Provides the ability to write the report business logic. This method will be called by  at runtime.
    /// The method should compute data and populate the data tables that will be returned to .
    /// </remarks>
    public void processReport()
    {
        contract = this.parmDataContract() as METExciseRegisterReceiptVarianceContract;

        utcdatetime fromDateTime,toDateTime;
        TimeZone timeZone = DateTimeUtil::getUserPreferredTimeZone();
        fromDateTime = datetobeginUtcDateTime(contract.parmFromDate(), timeZone);
        toDateTime   = datetoendUtcDateTime(contract.parmToDate(),timeZone);

        VendAccount vendAccount = contract.parmVendorId();

        METExciseRegisterEntry            exciseRegister;
        METInventTable                    metInventTable;
        InventItemIdLookupSimpleView      InventItemIdLookupSimpleView;

        insert_recordset varianceTmpTable (Site, SiteBondNumber, ItemId, DutyOriginCountryCode, DutyRate, DutyRateReceived, TariffItemCode, VendAccount, ReceiptUnitOfMeasure, AlcoholContent, ItemName)
            select Site, SiteBondNumber, ItemId, DutyOriginCountryCode, sum(CustomDuty), sum(CustomValue), TariffItemCode, OriginParty, ReceiptUnitOfMeasure
            from exciseRegister
                group by Site, SiteBondNumber, ItemId, DutyOriginCountryCode, TariffItemCode, OriginParty, ReceiptUnitOfMeasure
                where exciseRegister.OriginType == METOriginType::PurchaseOrder
                &&    exciseRegister.CreatedDateTime >= fromDateTime
                &&    exciseRegister.CreatedDateTime <= toDateTime
                &&   (exciseRegister.CustomDuty - exciseRegister.CustomValue) != 0
                &&   (vendAccount =='' || exciseRegister.OriginParty == vendAccount)
            join AlcoholContent
            from metInventTable
                group by ItemId,AlcoholContent
                where metInventTable.ItemId == exciseRegister.ItemId
            join ProductName
            from InventItemIdLookupSimpleView
                group by ItemId,ProductName
                where InventItemIdLookupSimpleView.ItemId == exciseRegister.ItemId;
    }
